["13021"]={["Title"]="Starszy Igasho", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="Dobrze wiedzieć, że@ludzie z@tych krain nadal składają hołd starszym rasom. Życzę ci szczęścia, YOUR_NAME i@ofiaruje tę monetę...", ["Translator"]="Orina"},
["13022"]={["Title"]="Starszy Nurgen", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="Dobrze wiedzieć, że@ludzie tych ziem nadal oddają cześć starszym rasom. Życzę ci szczęścia, YOUR_NAME i@oferuję tę monetę.", ["Translator"]="Orina"},
