["30419"]={["Title"]="Błękitne pióro dla farmera Funga", ["Objectives"]="", ["Description"]="", ["Progress"]="Cześć ci, YOUR_RACE7!", ["Completion"]="To bardzo rzadkie błękitne pióro. Dziękuję ci.", ["Translator"]="Shaula"},
["30420"]={["Title"]="Bagienna lilia dla farmera Funga", ["Objectives"]="", ["Description"]="", ["Progress"]="Nie ma to, jak zakończyć sadzenie.", ["Completion"]="W rzeczy samej, to rzadki kwiat.", ["Translator"]="Shaula"},
["30421"]={["Title"]="Danie dla farmera Funga", ["Objectives"]="", ["Description"]="", ["Progress"]="Chyba słyszę, jak burczy mi w@brzuchu.", ["Completion"]="Skąd wiedziałeś, że@to moje ulubione danie? Dzięki.", ["Translator"]="Shaula"},
["30422"]={["Title"]="Odłamek rubinu dla Fish", ["Objectives"]="", ["Description"]="", ["Progress"]="Cały ranek zaganiam jaki.", ["Completion"]="Ooch, nigdy żem nie@widziała tak@piknego czerwonego kamyka. Dzięki, YOUR_NAME!", ["Translator"]="Shaula"},
