["30426"]={["Title"]="Bagienna lilia dla Fish", ["Objectives"]="", ["Description"]="", ["Progress"]="Cały ranek pływam z@rybami.", ["Completion"]="Mój tatko zawsze powiadał, że@te kwiaty przynoszą łogromne szczęście. Dzięki, YOUR_NAME!", ["Translator"]="Shaula"},
["30427"]={["Title"]="Danie dla Fish", ["Objectives"]="", ["Description"]="", ["Progress"]="Cały ranek wspinam się po@drzewach.", ["Completion"]="O rany, moje ulubione jadło! Dzięki, YOUR_NAME!", ["Translator"]="Shaula"},
