["41674"]={["Title"]="Zamówienie: słowo intelektu", ["Objectives"]="", ["Description"]="", ["Progress"]="Witaj, zaklinaczu. Zakładam, że@widziałeś nasze zamówienie. Czy masz czar?", ["Completion"]="Kirin Tor dziękuje Ci.", ["Translator"]="Orina"},
