["41678"]={["Title"]="Zlecenie: Gunpack", ["Objectives"]="", ["Description"]="", ["Progress"]="Tak?", ["Completion"]="Miło cię widzieć, YOUR_RACE7 inżynierze. Valarjarowie są wdzięczni za@pomoc.", ["Translator"]="Helldream"},
