["51042"]={["Title"]="Potrzebne zapasy: ruda monelitu", ["Objectives"]="", ["Description"]="", ["Progress"]="YOUR_GENDER(Przybyłeś;Przybyłaś) tu, by@dostarczyć nam zapasy?", ["Completion"]="Dziękujemy ci za@pomoc, YOUR_CLASS7. Bardzo potrzebowaliśmy tej rudy.", ["Translator"]="Shaula"},
