["52358"]={["Title"]="Zlecenie: zaklęcie rzucane na pierścień - Pieczęć Pośpiechu", ["Objectives"]="", ["Description"]="", ["Progress"]="YOUR_GENDER(Przybyłeś;Przybyłaś) tu, by@dostarczyć nam zapasy?", ["Completion"]="Dziękujemy ci za@pomoc, YOUR_GENDER(zaklinaczu;zaklinaczko). Bardzo potrzebowaliśmy tych zwojów.", ["Translator"]="Shaula"},
